# Initially generated by GitHub Copilot.
from __future__ import annotations

import os
from pathlib import Path
import tempfile

from repo_util.common import run_cmd
from repo_util.repo_selection import RepoInfo


def read_commit_message(message: str | None, message_file: str | None) -> str:
    if message_file is not None:
        with open(message_file, "r", encoding="utf-8") as file_obj:
            commit_message = file_obj.read()
    else:
        commit_message = message

    if not commit_message:
        raise ValueError("Commit message must not be empty")
    return commit_message


def has_staged_changes(repo_dir: Path) -> bool:
    result = run_cmd(
        ["git", "-C", str(repo_dir), "diff", "--cached", "--quiet", "--exit-code"]
    )
    if result.returncode in (0, 1):
        return result.returncode == 1
    raise RuntimeError(
        result.stderr.strip() or f"Failed to inspect staged changes in {repo_dir}"
    )


def get_staged_summary(repo_dir: Path) -> dict[str, int]:
    result = run_cmd(["git", "-C", str(repo_dir), "diff", "--cached", "--numstat"])
    if result.returncode != 0:
        raise RuntimeError(
            result.stderr.strip() or f"Failed to summarize staged changes in {repo_dir}"
        )

    lines = [line for line in result.stdout.splitlines() if line.strip()]
    insertions = 0
    deletions = 0
    for line in lines:
        added_str, deleted_str, _path = line.split("\t", 2)
        if added_str != "-":
            insertions += int(added_str)
        if deleted_str != "-":
            deletions += int(deleted_str)

    return {
        "files_changed": len(lines),
        "insertions": insertions,
        "deletions": deletions,
    }


def commit_repo(repo_dir: Path, message_file: Path) -> None:
    result = run_cmd(["git", "-C", str(repo_dir), "commit", "-F", str(message_file)])
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or result.stdout.strip())
    print(f"Committed {repo_dir.name}")


def push_repo(repo_dir: Path) -> None:
    result = run_cmd(["git", "-C", str(repo_dir), "push"])
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or result.stdout.strip())
    print(f"Pushed {repo_dir.name}")


def show_dry_run(
    repo_dir: Path,
    commit_message: str,
    staged_summary: dict[str, int],
    *,
    and_push: bool,
) -> None:
    print(f"Would commit {repo_dir.name}")
    print(
        "Summary: "
        f"{staged_summary['files_changed']} staged files, "
        f"{staged_summary['insertions']} insertions, "
        f"{staged_summary['deletions']} deletions"
    )
    if and_push:
        print("Would push after commit")
    print("Commit message:")
    print(commit_message)
    print("---")


def run_commit_across_repos(
    repo_infos: list[RepoInfo],
    *,
    message: str | None,
    message_file: str | None,
    dry_run: bool,
    and_push: bool,
) -> int:
    commit_message = read_commit_message(message, message_file)
    matching_repo_count = 0

    if dry_run:
        for repo_info in repo_infos:
            if not has_staged_changes(repo_info.path):
                continue
            staged_summary = get_staged_summary(repo_info.path)
            show_dry_run(
                repo_info.path,
                commit_message,
                staged_summary,
                and_push=and_push,
            )
            matching_repo_count += 1
    else:
        with tempfile.NamedTemporaryFile(
            mode="w", encoding="utf-8", delete=False, suffix=".txt"
        ) as tmp_file:
            tmp_file.write(commit_message)
            tmp_path = Path(tmp_file.name)

        try:
            for repo_info in repo_infos:
                if not has_staged_changes(repo_info.path):
                    continue
                commit_repo(repo_info.path, tmp_path)
                if and_push:
                    push_repo(repo_info.path)
                matching_repo_count += 1
        finally:
            os.unlink(tmp_path)

    if matching_repo_count == 0:
        print("No staged changes found in any selected repo.")
    elif dry_run:
        print(f"Dry run found staged changes in {matching_repo_count} repos.")
    elif and_push:
        print(f"Committed and pushed staged changes in {matching_repo_count} repos.")
    else:
        print(f"Committed staged changes in {matching_repo_count} repos.")

    return matching_repo_count
